module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic data,
    output logic start_shifting
);

    // State encoding: 0=S0, 1=S1, 2=S2, 3=S3, 4=S_FOUND
    typedef enum logic [2:0] {
        S0 = 3'b000,
        S1 = 3'b001,
        S2 = 3'b010,
        S3 = 3'b011,
        S_FOUND = 3'b100
    } state_type;

    state_type state, next_state;

    // State register (synchronous reset, active high)
    always_ff @(posedge clk) begin
        if (reset)
            state <= S0;
        else
            state <= next_state;
    end

    // Next-state logic
    always_comb begin
        case (state)
            S0: begin
                if (data == 1'b1)
                    next_state = S1;
                else
                    next_state = S0;
            end
            S1: begin
                if (data == 1'b1)
                    next_state = S2;
                else
                    next_state = S0;
            end
            S2: begin
                if (data == 1'b0)
                    next_state = S3;
                else
                    next_state = S1; // overlapping: '1' restarts at S1
            end
            S3: begin
                if (data == 1'b1)
                    next_state = S_FOUND;
                else
                    next_state = S0;
            end
            S_FOUND: begin
                next_state = S_FOUND;
            end
            default: next_state = S0;
        endcase
    end

    // Output logic: start_shifting is 1 only when we have reached the found state
    assign start_shifting = (state == S_FOUND);

endmodule

