module TopModule (
    input  clk,
    input  reset,
    input  [7:0] in,
    output reg [23:0] out_bytes,
    output reg done
);

    // State encoding
    typedef enum logic [1:0] {
        IDLE  = 2'b00,
        GET1  = 2'b01,
        GET2  = 2'b10,
        GET3  = 2'b11
    } state_t;

    state_t state, next_state;
    logic [1:0] byte_count;  // counts received bytes (1, 2, 3)
    logic [7:0] byte1, byte2, byte3;

    // -------------------------------------------------
    // FSM state register (positive edge triggered)
    // -------------------------------------------------
    always_ff @(posedge clk) begin
        if (reset) begin
            state     <= IDLE;
            byte_count<= 0;
            out_bytes <= 0;
            done      <= 1'b0;
        end else begin
            state     <= next_state;
            done      <= 1'b0;               // clear done each cycle

            case (state)
                IDLE: begin
                    if (in[3]) begin          // byte 1 found
                        byte_count <= 1;
                        byte1      <= in;
                        state      <= GET1;
                    end else begin
                        // discard byte
                        byte_count <= 0;
                        state      <= IDLE;
                    end
                end

                GET1: begin
                    byte_count <= 2;
                    byte2      <= in;
                    state      <= GET2;
                end

                GET2: begin
                    byte_count <= 3;
                    byte3      <= in;
                    state      <= GET3;
                end

                GET3: begin
                    // Assemble the 24-bit message
                    // out_bytes[23:16] = first byte (byte1)
                    // out_bytes[15:8]  = second byte (byte2)
                    // out_bytes[7:0]   = third byte (byte3)
                    out_bytes <= {byte1, byte2, byte3};
                    done      <= 1'b1;   // assert done in this cycle
                    state     <= IDLE;   // ready for next message
                end
            endcase
        end
    end

    // Optional: combinational next-state logic if you prefer
    // always_comb begin
    //     next_state = state;
    //     // ... logic here ...
    // end

endmodule

