module TopModule (
    input  logic [3:0] x,
    output logic       f
);

    // Internal signals for each row of the K-map
    logic f00, f01, f11, f10;

    // Decode the 4-bit input into the four K-map cells
    // Row 00: x[3:4] = 00
    assign f00 = (x[3:2] == 2'b00) ? x[2] : 1'bz;  // don't-care, driven high for simplicity
    // Row 01: x[3:4] = 01
    assign f01 = (x[3:2] == 2'b01) ? (~x[2] & ~x[1]) : 1'bz;
    // Row 11: x[3:4] = 11
    assign f11 = (x[3:2] == 2'b11) ? (x[2] | x[1]) : 1'bz;
    // Row 10: x[3:4] = 10
    assign f10 = (x[3:2] == 2'b10) ? (~x[2] & x[1]) : 1'bz;

    // Combine the rows using a case statement to cover all states
    always_comb
    begin
        case (x[3:2])
            2'b00: f = f00;   // don't-care, default to 1
            2'b01: f = f01;
            2'b11: f = f11;
            2'b10: f = f10;
            default: f = 1'b0;
        endcase
    end

endmodule

