module TopModule (
    input  clk,
    input  resetn,
    input  in,
    output out
);

    // Internal wire to hold the shift register output
    wire [3:0] q;

    // Four D flip-flops chained together to form a 4-bit shift register
    // The first flop takes the external 'in' input
    // Subsequent flops take the output of the previous flop
    dff_rstn u0 (
        .clk (clk),
        .rstn(resetn),
        .d (in),
        .q (q[0])
    );

    dff_rstn u1 (
        .clk (clk),
        .rstn(resetn),
        .d (q[0]),
        .q (q[1])
    );

    dff_rstn u2 (
        .clk (clk),
        .rstn(resetn),
        .d (q[1]),
        .q (q[2])
    );

    dff_rstn u3 (
        .clk (clk),
        .rstn(resetn),
        .d (q[2]),
        .q (q[3])
    );

    // Output the value of the last (4th) flip-flop
    assign out = q[3];

endmodule

// Synthesizable D flip-flop with active-low synchronous reset
// The reset is applied on the positive edge of the clock
module dff_rstn (
    input  clk,
    input  rstn,
    input  d,
    output q
);

    reg q;

    always @(posedge clk or negedge rstn) begin
        if (!rstn) begin
            q <= 1'b0;
        end else begin
            q <= d;
        end
    end

endmodule

