module TopModule(
    input  clk,
    input  reset,
    input  [2:0] s,
    output fr2,
    output fr1,
    output fr0,
    output dfr
);

    // Internal state encoding
    // 00 = below s[0] (maximum flow)
    // 01 = between s[1] and s[0]
    // 10 = between s[2] and s[1]
    // 11 = above s[2] (no flow)
    reg [1:0] state, next_state;

    // Decode current sensor pattern
    wire s2 = s[2];
    wire s1 = s[1];
    wire s0 = s[0];

    // --- Next-state logic ---
    always @(*) begin
        next_state = state; // default: hold

        case (state)
            2'b00: begin // currently below s[0]
                if (~s0 & ~s1 & ~s2) begin // still below
                    next_state = 2'b00;
                end else if (s0 & ~s1 & ~s2) begin // crossed into between s[1] and s[0]
                    next_state = 2'b01;
                end else if (s1 & ~s2) begin // crossed into between s[2] and s[1]
                    next_state = 2'b10;
                end else if (s2) begin // crossed above s[2]
                    next_state = 2'b11;
                end
            end

            2'b01: begin // currently between s[1] and s[0]
                if (~s0 & ~s1 & ~s2) begin // dropped below s[0]
                    next_state = 2'b00;
                end else if (s0 & ~s1) begin // still between
                    next_state = 2'b01;
                end else if (s1 & ~s2) begin // crossed above s[1]
                    next_state = 2'b10;
                end else if (s2) begin // crossed above s[2]
                    next_state = 2'b11;
                end
            end

            2'b10: begin // currently between s[2] and s[1]
                if (~s0 & ~s1 & ~s2) begin // dropped below s[0]
                    next_state = 2'b00;
                end else if (s0 & ~s1) begin // crossed below s[1]
                    next_state = 2'b01;
                end else if (s1 & ~s2) begin // still between s[2] and s[1]
                    next_state = 2'b10;
                end else if (s2) begin // crossed above s[2]
                    next_state = 2'b11;
                end
            end

            2'b11: begin // currently above s[2]
                if (~s0 & ~s1 & ~s2) begin // dropped below s[0]
                    next_state = 2'b00;
                end else if (s0 & ~s1) begin // crossed below s[1]
                    next_state = 2'b01;
                end else if (s1 & ~s2) begin // crossed below s[2]
                    next_state = 2'b10;
                end else if (s2) begin // still above
                    next_state = 2'b11;
                end
            end
        endcase
    end

    // --- Output logic (continuous assignments) ---
    // These assignments drive the outputs based on the current state and sensors.

    // Default state assignments (all outputs 0)
    assign fr0 = 1'b0;
    assign fr1 = 1'b0;
    assign fr2 = 1'b0;
    assign dfr = 1'b0;

    always @(*) begin
        case (state)
            2'b00: begin // below s[0] -> maximum flow
                fr0 = 1'b1;
                fr1 = 1'b1;
                fr2 = 1'b1;
                dfr = 1'b1;
            end
            2'b01: begin // between s[1] and s[0] -> nominal fr0
                fr0 = 1'b1;
                fr1 = 1'b0;
                fr2 = 1'b0;
                dfr = 1'b0;
            end
            2'b10: begin // between s[2] and s[1] -> nominal fr0
                fr0 = 1'b1;
                fr1 = 1'b0;
                fr2 = 1'b0;
                dfr = 1'b0;
            end
            2'b11: begin // above s[2] -> no flow
                fr0 = 1'b0;
                fr1 = 1'b0;
                fr2 = 1'b0;
                dfr = 1'b0;
            end
        endcase
    end

    // --- Synchronous reset and state flip-flops ---
    // We use a register 'state_reg' to hold the state so we can 
    // initialize it correctly on reset without driving outputs illegally 
    // during the reset cycle simulation.
    reg [1:0] state_reg;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            // Active-high synchronous reset: equivalent to long-time low water level
            state_reg <= 2'b00;
        end else begin
            state_reg <= next_state;
        end
    end

    // Output assignments driven by the registered state
    // This ensures outputs are stable and correctly reflect the state.
    assign fr0 = (state_reg == 2'b00) | (state_reg == 2'b01) | (state_reg == 2'b10);
    assign fr1 = (state_reg == 2'b00) | (state_reg == 2'b10);
    assign fr2 = (state_reg == 2'b00);
    assign dfr = (state_reg == 2'b00);

endmodule

