module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

// State encoding
typedef enum logic [2:0] {
    WALK_LEFT,    // 000 - walking left on ground
    WALK_RIGHT,   // 001 - walking right on ground
    FALL,         // 010 - falling (aaah)
    DIG,          // 011 - digging on ground
    SPLATTER      // 100 - splattered (terminal state)
} state_t;

// State registers
state_t state, next_state;

// Fall counter - counts cycles spent falling
logic [4:0] fall_counter, next_fall_counter;

// Direction register - stores walking direction when leaving ground
logic walking_left_reg, next_walking_left;

// Output assignments (Moore machine)
assign walk_left   = (state == WALK_LEFT);
assign walk_right  = (state == WALK_RIGHT);
assign aaah        = (state == FALL);
assign digging     = (state == DIG);

// Next state logic - always combinational
always_comb begin
    next_state = state;
    next_fall_counter = fall_counter;
    next_walking_left = walking_left_reg;

    case (state)
        WALK_LEFT: begin
            // Priority: fall > dig > switch direction
            if (!ground) begin
                // Ground disappeared - start falling
                next_state = FALL;
                next_fall_counter = 1;
                next_walking_left = 1'b1; // Was walking left
            end else if (dig) begin
                // Start digging
                next_state = DIG;
            end else if (bump_right) begin
                // Bumped on right while walking left -> switch to right
                next_state = WALK_RIGHT;
            end else if (bump_left) begin
                // Bumped on left while walking left -> switch to right (both sides rule)
                next_state = WALK_RIGHT;
            end
            // If bumped in same cycle as ground disappears, fall has higher precedence
            // Already handled by !ground check first
        end

        WALK_RIGHT: begin
            if (!ground) begin
                next_state = FALL;
                next_fall_counter = 1;
                next_walking_left = 1'b0; // Was walking right
            end else if (dig) begin
                next_state = DIG;
            end else if (bump_left) begin
                next_state = WALK_LEFT;
            end else if (bump_right) begin
                next_state = WALK_LEFT; // Bumped on right while walking right -> switch to left
            end
        end

        FALL: begin
            if (ground) begin
                // Hit ground - check fall duration
                if (fall_counter > 20) begin
                    // Fell for more than 20 cycles -> splatter
                    next_state = SPLATTER;
                end else begin
                    // Resume walking in original direction
                    if (walking_left_reg) begin
                        next_state = WALK_LEFT;
                    end else begin
                        next_state = WALK_RIGHT;
                    end
                end
            end else begin
                // Still falling - increment counter
                // Being bumped while falling has no effect
                next_fall_counter = fall_counter + 1;
            end
        end

        DIG: begin
            if (!ground) begin
                // Ground disappeared while digging - start falling
                next_state = FALL;
                next_fall_counter = 1;
                next_walking_left = walking_left_reg; // Remember direction
            end else if (!dig) begin
                // Stop digging - resume walking in same direction
                if (walking_left_reg) begin
                    next_state = WALK_LEFT;
                end else begin
                    next_state = WALK_RIGHT;
                end
            end
            // Being bumped while digging has no effect
        end

        SPLATTER: begin
            // Terminal state - stay splattered
            next_state = SPLATTER;
        end
    endcase
end

// State, counter, and direction register update on positive edge of clock
always_ff @(posedge clk or posedge areset) begin
    if (areset) begin
        state <= WALK_LEFT;
        fall_counter <= 0;
        walking_left_reg <= 1'b1; // Default to walking left after reset
    end else begin
        state <= next_state;
        fall_counter <= next_fall_counter;
        walking_left_reg <= next_walking_left;
    end
end

endmodule

