module TopModule (
    input  clk,
    input  reset,
    output ena    [2:0],
    output q      [15:0]
);

    // Internal registers for the four BCD digits (ones, tens, hundreds, thousands)
    reg [3:0] ones;     // q[3:0]
    reg [3:0] tens;   // q[7:4]
    reg [3:0] hun;    // q[11:8]
    reg [3:0] thou;   // q[15:12]

    // Internal enable signals (active-high, enable the next digit's increment)
    wire ena_tens;   // enable tens digit
    wire ena_hun;    // enable hundreds digit
    wire ena_thou;   // enable thousands digit

    // ---- BCD Increment Logic ----
    // Ones digit always increments (or resets). It generates a carry if it was 9.
    always @(posedge clk) begin
        if (reset) begin
            ones <= 4'b0;
        end else begin
            if (ones == 4'd9)
                ones <= 4'b0;
            else
                ones <= ones + 1'b1;
        end
    end

    // Tens digit increments when ones carried (ones rolled over from 9).
    always @(posedge clk) begin
        if (reset) begin
            tens <= 4'b0;
        end else begin
            if (tens == 4'd9 && ones == 4'd9)
                tens <= 4'b0;
            else if (ones == 4'd9)
                tens <= tens + 1'b1;
            else
                tens <= tens;
        end
    end

    // Hundreds digit increments when tens and ones both carry (i.e., counted to 99).
    always @(posedge clk) begin
        if (reset) begin
            hun <= 4'b0;
        end else begin
            if (hun == 4'd9 && tens == 4'd9 && ones == 4'd9)
                hun <= 4'b0;
            else if (tens == 4'd9 && ones == 4'd9)
                hun <= hun + 1'b1;
            else
                hun <= hun;
        end
    end

    // Thousands digit increments when hundreds, tens, and ones all carry (counted to 999).
    always @(posedge clk) begin
        if (reset) begin
            thou <= 4'b0;
        end else begin
            if (thou == 4'd9 && hun == 4'd9 && tens == 4'd9 && ones == 4'd9)
                thou <= 4'b0;
            else if (hun == 4'd9 && tens == 4'd9 && ones == 4'd9)
                thou <= thou + 1'b1;
            else
                thou <= thou;
        end
    end

    // ---- Enable signal assignments ----
    // ena[2] enables the hundreds digit
    // ena[1] enables the tens digit
    // ena[0] is not used for a lower digit as ones always increments; drive it low.
    assign ena = {ena_thou, ena_hun, ena_tens};

    // Assign the combined 16-bit output q
    assign q = {thou, hun, tens, ones};

    // Logic for enable signals (they pulse high when the corresponding
    // digit should increment in the next cycle).
    assign ena_tens  = (ones == 4'd9);          // tens increments when ones rolls over
    assign ena_hun   = (tens == 4'd9 && ones == 4'd9); // hun increments when tens&ones roll
    assign ena_thou  = (hun == 4'd9 && tens == 4'd9 && ones == 4'd9); // thou increments at 999

endmodule
